// game.exe's static initialisers as C++ (docs/notes/standalone.md, S3). static_init.cpp is generated by
// tools/gen_static_init.py: one template, StaticInitialisers(Do&), states what each initialiser does in
// list order, through the operations below. Three visitors give it meaning:
//   Run      does it: the standalone image runs it before WinMain (RunStaticInitialisers).
//   Check    evaluates the stores and float folds and remembers the values (the last write to an
//            address wins); the verify build compares them with what the original's initialisers left
//            in memory (tests/verify/verify_static_init.cpp).
//   Targets  collects the call targets and exit functions, so the standalone check can say which have
//            no code in the image yet.
// Addresses are game.exe's (the image in the standalone build, the original in the hook build).
#pragma once

#include <cmath>
#include <cstdint>
#include <cstring>
#include <map>
#include <vector>

namespace ei::static_init {

// A call's EAX. The Check visitor does not call anything: a stored result is not compared.
struct Result {
    std::uint32_t value;
};

template <class>
using Word = std::uint32_t;

// The CRT's atexit in game.exe, which Run::AtExit reaches through GameAtExit (originals_library.h).
constexpr std::uintptr_t kCrtAtExit = 0x006E727B;

class Run {
public:
    void Begin(std::uintptr_t) {}
    // The once-only guard of a global (a bit in a flag byte): false when the bit is already set.
    bool Once(std::uintptr_t flag, std::uint8_t bit) {
        std::uint8_t& flags = *reinterpret_cast<std::uint8_t*>(flag);
        if (flags & bit) return false;
        flags = static_cast<std::uint8_t>(flags | bit);
        return true;
    }
    void Store(std::uintptr_t address, std::uint32_t value) { *reinterpret_cast<std::uint32_t*>(address) = value; }
    void Store(std::uintptr_t address, Result result) { Store(address, result.value); }
    template <class T>
    void StoreFloat(std::uintptr_t address, T value) { *reinterpret_cast<float*>(address) = static_cast<float>(value); }
    void Fill(std::uintptr_t address, std::uint32_t value, std::uint32_t count) {
        auto* to = reinterpret_cast<std::uint32_t*>(address);
        for (std::uint32_t i = 0; i < count; ++i) to[i] = value;
    }
    std::uint32_t Dword(std::uintptr_t address) const { return *reinterpret_cast<const std::uint32_t*>(address); }
    float Float(std::uintptr_t address) const { return *reinterpret_cast<const float*>(address); }
    double Double(std::uintptr_t address) const { return *reinterpret_cast<const double*>(address); }
    // FLDLN2; FLD x; FYL2X.
    static double Log(double x) { return std::log(x); }
    // A buffer on the initialiser's stack frame (SUB ESP, n; LEA reg, [ESP + offset]).
    std::uint32_t Local(std::uint32_t offset) { return static_cast<std::uint32_t>(reinterpret_cast<std::uintptr_t>(frame_ + offset)); }

    template <class... A>
    Result Cdecl(std::uintptr_t fn, A... args) {
        return {reinterpret_cast<std::uint32_t(__cdecl*)(Word<A>...)>(fn)(static_cast<std::uint32_t>(args)...)};
    }
    template <class... A>
    Result Stdcall(std::uintptr_t fn, A... args) {
        return {reinterpret_cast<std::uint32_t(__stdcall*)(Word<A>...)>(fn)(static_cast<std::uint32_t>(args)...)};
    }
    template <class... A>
    Result Thiscall(std::uintptr_t fn, std::uintptr_t object, A... args) {
        return {reinterpret_cast<std::uint32_t(__thiscall*)(void*, Word<A>...)>(fn)(reinterpret_cast<void*>(object),
                                                                                      static_cast<std::uint32_t>(args)...)};
    }
    // CALL [slot]: a Win32 function through game.exe's import address table.
    template <class... A>
    Result Import(std::uintptr_t slot, A... args) {
        return Stdcall(*reinterpret_cast<const std::uintptr_t*>(slot), args...);
    }
    // The CRT's atexit (006E727B) with an exit function of game.exe.
    void AtExit(std::uintptr_t fn);

private:
    alignas(16) unsigned char frame_[0x400] = {};
};

class Check {
public:
    struct Value {
        std::uint32_t bits;
        bool isFloat;
        bool known;               // false: a later call's result was stored here
        std::uintptr_t initialiser;
    };
    struct Guard {
        std::uintptr_t flag;
        std::uint8_t bit;
        std::uintptr_t initialiser;
    };

    void Begin(std::uintptr_t initialiser) { initialiser_ = initialiser; }
    bool Once(std::uintptr_t flag, std::uint8_t bit) {
        guards.push_back({flag, bit, initialiser_});
        return true;
    }
    void Store(std::uintptr_t address, std::uint32_t value) { values[address] = {value, false, true, initialiser_}; }
    void Store(std::uintptr_t address, Result) { values[address] = {0, false, false, initialiser_}; }
    template <class T>
    void StoreFloat(std::uintptr_t address, T value) {
        const float f = static_cast<float>(value);
        std::uint32_t bits;
        std::memcpy(&bits, &f, 4);
        values[address] = {bits, true, true, initialiser_};
    }
    void Fill(std::uintptr_t address, std::uint32_t value, std::uint32_t count) {
        for (std::uint32_t i = 0; i < count; ++i) Store(address + 4 * i, value);
    }
    // Reads the original's memory as the initialiser did: a copy compares the two addresses' contents.
    std::uint32_t Dword(std::uintptr_t address) const { return *reinterpret_cast<const std::uint32_t*>(address); }
    float Float(std::uintptr_t address) const { return *reinterpret_cast<const float*>(address); }
    double Double(std::uintptr_t address) const { return *reinterpret_cast<const double*>(address); }
    static double Log(double x) { return std::log(x); }
    std::uint32_t Local(std::uint32_t) { return 0; }
    template <class... A>
    Result Cdecl(std::uintptr_t, A...) { return {0}; }
    template <class... A>
    Result Stdcall(std::uintptr_t, A...) { return {0}; }
    template <class... A>
    Result Thiscall(std::uintptr_t, std::uintptr_t, A...) { return {0}; }
    template <class... A>
    Result Import(std::uintptr_t, A...) { return {0}; }
    void AtExit(std::uintptr_t) {}

    std::map<std::uintptr_t, Value> values;
    std::vector<Guard> guards;

private:
    std::uintptr_t initialiser_ = 0;
};

class Targets {
public:
    void Begin(std::uintptr_t) {}
    bool Once(std::uintptr_t, std::uint8_t) { return true; }
    void Store(std::uintptr_t, std::uint32_t) {}
    void Store(std::uintptr_t, Result) {}
    template <class T>
    void StoreFloat(std::uintptr_t, T) {}
    void Fill(std::uintptr_t, std::uint32_t, std::uint32_t) {}
    std::uint32_t Dword(std::uintptr_t) const { return 0; }
    float Float(std::uintptr_t) const { return 0; }
    double Double(std::uintptr_t) const { return 0; }
    static double Log(double) { return 0; }
    std::uint32_t Local(std::uint32_t) { return 0; }
    template <class... A>
    Result Cdecl(std::uintptr_t fn, A...) { return Call(fn); }
    template <class... A>
    Result Stdcall(std::uintptr_t fn, A...) { return Call(fn); }
    template <class... A>
    Result Thiscall(std::uintptr_t fn, std::uintptr_t, A...) { return Call(fn); }
    template <class... A>
    Result Import(std::uintptr_t slot, A...) {
        imports.push_back(slot);
        return {0};
    }
    void AtExit(std::uintptr_t fn) {
        exits.push_back(fn);
        calls.push_back(kCrtAtExit);
    }

    std::vector<std::uintptr_t> calls, imports, exits;

private:
    Result Call(std::uintptr_t fn) {
        calls.push_back(fn);
        return {0};
    }
};

template <class Do>
void StaticInitialisers(Do& d);

// The standalone image: runs the initialisers in list order (call before WinMain).
void RunStaticInitialisers();
// The standalone check: logs the call targets and exit functions with no code in the image yet.
// Returns their number.
int ReportMissingTargets();

} // namespace ei::static_init
